begin;
-- Links select a record; Google identity, email, expiry and stored role remain authoritative.
create or replace function public.accept_selected_invitation(p_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare inv public.invitations;begin if not private.google_session() or not exists(select 1 from public.profiles where id=auth.uid() and status='ACTIVE') then raise insufficient_privilege;end if;select * into inv from public.invitations where id=p_id and auth_user_id=auth.uid() and email=lower(auth.jwt()->>'email') and status='PENDING' and expires_at>now() order by created_at desc limit 1 for update;if inv.id is null then raise exception 'No valid invitation' using errcode='42501';end if;if inv.role in ('ORG_ADMIN','ORGANIZER','PLATFORM_ADMIN') and auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'MFA_REQUIRED' using errcode='42501';end if;insert into public.organization_members(organization_id,user_id,role) values(inv.organization_id,auth.uid(),inv.role) on conflict(organization_id,user_id) do nothing;update public.invitations set status='ACCEPTED' where id=inv.id;perform private.audit(inv.organization_id,'invitation.accepted',inv.id);return inv.organization_id;end $$;
revoke all on function public.accept_selected_invitation(uuid) from public,anon;
grant execute on function public.accept_selected_invitation(uuid) to authenticated;
commit;
